#pragma once
#include <cinttypes>
#include <filesystem>
#include <functional>
#include <memory>
#include <string>
#include <utility>

#include "error.hpp"

// ToDo:
// - Figure out a way to let the lexer output line and character information?

namespace blitz {
	struct token {
		std::pair<uint64_t, uint64_t> location;
		std::string                   text;
		enum class variant : uint64_t {
			NONE, // There is no token here.
			UNKNOWN, // We have absolutely no fucking clue.
			ENDOFFILE, // End of the file.
			NEWLINE, // New Line.
			SEPARATOR, // Command Separator. (':')
			CONTROL, // All kinds of control signals
			SYMBOL, // All kinds of symbols.
			COMMENT, // ; Whatever
			TEXT, // HelloWorld
			STRING, // "HelloWorld"
			INTEGER, // 1, 1% (without the %)
			REAL, // 1.0, 1# (without the #)
		} type;

		std::string to_string() const;

		bool operator==(blitz::token::variant rhs) const;
		bool operator==(std::string const& rhs) const;
	};

	class lexer {
		std::filesystem::path _file;
		std::string           _data; // Entire file, so that saving and restoring state is trivial.
		size_t                _offset;
		size_t                _text_end; // Where the last name ended, to tell `Name$` apart from `$Hex`.

		// Current location in the file.
		std::pair<uint64_t, uint64_t> _location;

		blitz::token _current;
		blitz::token _next;

		public:
		~lexer();
		lexer(std::filesystem::path file);

		/** Where the text of a file comes from before the disk is asked: Tools that edit programs (the language server) keep
		 * the unsaved text of the files they have open here. Gets the path as it is about to be read and fills in the text,
		 * returns false to read the file from disk. Empty (the default) always reads from disk. */
		static void set_source_override(std::function<bool(std::filesystem::path const&, std::string&)> provider);

		struct state {
			size_t                        offset;
			std::pair<uint64_t, uint64_t> location;
			blitz::token                  current;
			blitz::token                  next;
		};

		/** Save the current state for future failure recovery.
		 */
		blitz::lexer::state save_state();

		/** Try and restore the saved state in case parsing failed.
		 */
		void load_state(blitz::lexer::state);

		/** Retrieve the current token information.
		 */
		blitz::token current();

		/** Retrieve the next token in the given stream.
		 *
		 * This will replace the current token.
		 */
		blitz::token next();

		/** Peek at the next token in the given stream.
		 *
		 * The current token will remain in-tact.
		 */
		blitz::token peek();

		public:
		std::filesystem::path file();

		private:
		blitz::token scan();
	};
} // namespace blitz
